Trie *trie_new(void)
{
	Trie *new_trie;
	new_trie = (Trie *) malloc(sizeof(Trie));
	if (new_trie == NULL) {
		return NULL;
	}
	new_trie->root_node = NULL;
	return new_trie;
}

static void trie_free_list_push(TrieNode **list, TrieNode *node)
{
	node->data = *list;
	*list = node;
}

static TrieNode *trie_free_list_pop(TrieNode **list)
{
	TrieNode *result;
	result = *list;
	*list = result->data;
	return result;
}

void trie_free(Trie *trie)
{
	TrieNode *free_list;
	TrieNode *node;
	int i;
	free_list = NULL;
	if (trie->root_node != NULL) {
		trie_free_list_push(&free_list, trie->root_node);
	}
	while (free_list != NULL) {
		node = trie_free_list_pop(&free_list);
		for (i=0; i<256; ++i) {
			if (node->next[i] != NULL) {
				trie_free_list_push(&free_list, node->next[i]);
			}
		}
		free(node);
	}
	free(trie);
}

static TrieNode *trie_find_end(Trie *trie, char *key)
{
	TrieNode *node;
	char *p;
	node = trie->root_node;
	for (p=key; *p != '\0'; ++p) {
		if (node == NULL) {
			return NULL;
		}
		node = node->next[(unsigned char) *p];
	}
	return node;
}

static TrieNode *trie_find_end_binary(Trie *trie, unsigned char *key,
                                      int key_length)
{
	TrieNode *node;
	int j;
	int c;
	node = trie->root_node;
	for (j=0; j<key_length; j++) {
		if (node == NULL) {
			return NULL;
		}
		c = (unsigned char) key[j];
		node = node->next[c];
	}
	return node;
}

static void trie_insert_rollback(Trie *trie, unsigned char *key)
{
	TrieNode *node;
	TrieNode **prev_ptr;
	TrieNode *next_node;
	TrieNode **next_prev_ptr;
	unsigned char *p;
	node = trie->root_node;
	prev_ptr = &trie->root_node;
	p = key;
	while (node != NULL) {
		next_prev_ptr = &node->next[(unsigned char) *p];
		next_node = *next_prev_ptr;
		++p;
		--node->use_count;
		if (node->use_count == 0) {
			free(node);
			if (prev_ptr != NULL) {
				*prev_ptr = NULL;
			}
			next_prev_ptr = NULL;
		}
		node = next_node;
		prev_ptr = next_prev_ptr;
	}
}

int trie_insert(Trie *trie, char *key, TrieValue value)
{
	TrieNode **rover;
	TrieNode *node;
	char *p;
	int c;
	if (value == TRIE_NULL) {
		return 0;
	}
	node = trie_find_end(trie, key);
	if (node != NULL && node->data != TRIE_NULL) {
		node->data = value;
		return 1;
	}
	rover = &trie->root_node;
	p = key;
	for (;;) {
		node = *rover;
		if (node == NULL) {
			node = (TrieNode *) calloc(1, sizeof(TrieNode));
			if (node == NULL) {
				trie_insert_rollback(trie,
				                     (unsigned char *) key);
				return 0;
			}
			node->data = TRIE_NULL;
			*rover = node;
		}
		++node->use_count;
		c = (unsigned char) *p;
		if (c == '\0') {
			node->data = value;
			break;
		}
		rover = &node->next[c];
		++p;
	}
	return 1;
}

int trie_insert_binary(Trie *trie, unsigned char *key, int key_length,
                       TrieValue value)
{
	TrieNode **rover;
