	if (value == TRIE_NULL) {
		return 0;
	}
	node = trie_find_end_binary(trie, key, key_length);
	if (node != NULL && node->data != TRIE_NULL) {
		node->data = value;
		return 1;
	}
	rover = &trie->root_node;
	p = 0;
	for (;;) {
		node = *rover;
		if (node == NULL) {
			node = (TrieNode *) calloc(1, sizeof(TrieNode));
			if (node == NULL) {
				trie_insert_rollback(trie, key);
				return 0;
			}
			node->data = TRIE_NULL;
			*rover = node;
		}
		++node->use_count;
		c = (unsigned char) key[p];
		if (p == key_length) {
			node->data = value;
			break;
		}
		rover = &node->next[c];
		++p;
	}
	return 1;
}

int trie_remove_binary(Trie *trie, unsigned char *key, int key_length)
{
	TrieNode *node;
	TrieNode *next;
	TrieNode **last_next_ptr;
	int p, c;
	node = trie_find_end_binary(trie, key, key_length);
	if (node != NULL && node->data != TRIE_NULL) {
		node->data = TRIE_NULL;
	} else {
		return 0;
	}
	node = trie->root_node;
	last_next_ptr = &trie->root_node;
	p = 0;
	for (;;) {
		c = (unsigned char) key[p];
		next = node->next[c];
		--node->use_count;
		if (node->use_count <= 0) {
			free(node);
			if (last_next_ptr != NULL) {
				*last_next_ptr = NULL;
				last_next_ptr = NULL;
			}
		}
		if (p == key_length) {
			break;
		} else {
			++p;
		}
		if (last_next_ptr != NULL) {
			last_next_ptr = &node->next[c];
		}
		node = next;
	}
	return 1;
}

