	while (slist_iter_has_more(&iter)) {
		data = (int *) slist_iter_next(&iter);
		++counter;
		if ((counter % 2) == 0) {
			slist_iter_remove(&iter);
			slist_iter_remove(&iter);
		}
	}
	assert(slist_iter_next(&iter) == SLIST_NULL);
	slist_iter_remove(&iter);
	assert(counter == 50);
	assert(slist_length(list) == 25);
	slist_free(list);
	list = NULL;
	counter = 0;
	slist_iterate(&list, &iter);
	while (slist_iter_has_more(&iter)) {
		data = (int *) slist_iter_next(&iter);
		++counter;
		if ((counter % 2) == 0) {
			slist_iter_remove(&iter);
		}
	}
	assert(counter == 0);
}

void test_slist_iterate_bad_remove(void)
{
	SListEntry *list;
	SListIterator iter;
	int values[49];
	int i;
	int *val;
	list = NULL;
	for (i=0; i<49; ++i) {
		values[i] = i;
		slist_prepend(&list, &values[i]);
	}
	slist_iterate(&list, &iter);
	while (slist_iter_has_more(&iter)) {
		val = slist_iter_next(&iter);
		if ((*val % 2) == 0) {
			assert(slist_remove_data(&list, int_equal, val) != 0);
			slist_iter_remove(&iter);
		}
	}
	slist_free(list);
}

void check_sorted_prop(SortedArray *sortedarray)
{
	unsigned int i;
	for (i = 1; i < sortedarray_length(sortedarray); i++) {
		assert(int_compare(
		                   sortedarray_get(sortedarray, i-1),
						   sortedarray_get(sortedarray, i)) <= 0);
	}
}

void free_sorted_ints(SortedArray *sortedarray)
{
	unsigned int i;
	for (i = 0; i < sortedarray_length(sortedarray); i++) {
		int *pi = (int*) sortedarray_get(sortedarray, i);
		free(pi);
	}
	sortedarray_free(sortedarray);
}

